/**
 * TASK: Keep a "recent searches" drop-down, newest first.
 *
 * Complete record(term) so the combo box model behaves like a search history:
 *   - a null term, or one that is blank after trimming, changes nothing;
 *   - otherwise use the TRIMMED term;
 *   - if an entry already matches it ignoring case, remove that old entry
 *     (the new spelling wins);
 *   - insert the term at position 0 so the newest search is first;
 *   - never keep more than MAX_ENTRIES (5) -- drop from the end;
 *   - leave index 0 selected;
 *   - finish by calling the provided refreshLabel().
 *
 * Example: record("java"), record("swing"), record("JAVA") leaves
 *          [JAVA, swing] and the label "JAVA, swing".
 */
import javax.swing.DefaultComboBoxModel;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class RecentSearchHistory extends JPanel {

    public static final int MAX_ENTRIES = 5;

    private final DefaultComboBoxModel<String> terms = new DefaultComboBoxModel<>();
    private final JComboBox<String> history = new JComboBox<>(terms);
    private final JLabel recent = new JLabel("(none)");

    public RecentSearchHistory() {
        history.setName("history");
        recent.setName("recent");
        history.setEditable(true);
        add(history);
        add(recent);
        refreshLabel();
    }

    /** Provided: lists the stored terms, oldest last. */
    private void refreshLabel() {
        if (terms.getSize() == 0) {
            recent.setText("(none)");
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < terms.getSize(); i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(terms.getElementAt(i));
        }
        recent.setText(sb.toString());
    }

    public void record(String term) {
