public class RecentSearchHistoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Container root, String name) {
        java.awt.Component c = find(root, name);
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            RecentSearchHistory panel = new RecentSearchHistory();
            java.awt.Component comboComp = find(panel, "history");
            check("combo box found", true, comboComp instanceof javax.swing.JComboBox);
            check("empty history label", "(none)", labelText(panel, "recent"));
            if (comboComp instanceof javax.swing.JComboBox) {
                javax.swing.JComboBox<?> combo = (javax.swing.JComboBox<?>) comboComp;
                check("history is editable", true, combo.isEditable());
                panel.record("  java  ");
                check("first term is trimmed and stored", "java", labelText(panel, "recent"));
                panel.record("swing");
                check("newest term comes first", "swing, java", labelText(panel, "recent"));
                check("newest term is selected", "swing", combo.getSelectedItem());
                panel.record("JAVA");
                check("case insensitive duplicate moves to the front", "JAVA, swing",
                        labelText(panel, "recent"));
                check("duplicate did not grow the list", 2, combo.getItemCount());
                panel.record("   ");
                panel.record(null);
                check("blank and null are ignored", "JAVA, swing", labelText(panel, "recent"));
                panel.record("a");
                panel.record("b");
                panel.record("c");
                check("five entries kept", 5, combo.getItemCount());
                panel.record("d");
                check("oldest entry dropped at the cap", "d, c, b, a, JAVA", labelText(panel, "recent"));
                check("still capped at five", 5, combo.getItemCount());
            } else {
                failures++;
                System.out.println("FAIL  history combo not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
